tool.command:

ln -s $input_sdf_path ./input_sdf_path.$input_sdf_path.ext;
#if $config_json:
  ln -s $config_json ./config_json.$config_json.ext;
#end if

gnina_select_pose

#if $config_json:
  --config ./config_json.$config_json.ext
#end if

--input_sdf_path ./input_sdf_path.$input_sdf_path.ext
--output_sdf_path $outname_output_sdf_path
;

mv $outname_output_sdf_path $output_sdf_path;
